CREATE TYPE "UserRole" AS ENUM ('MEMBER','ADMIN');
CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE','BLOCKED','WITHDRAWN');
CREATE TYPE "IntakeStatus" AS ENUM ('OPEN','CLOSED');
CREATE TYPE "ReservationStatus" AS ENUM ('PENDING','CONFIRMED','CANCELLED');
CREATE TYPE "ApplicationStatus" AS ENUM ('PENDING','CONFIRMED','CANCELLED');
CREATE TYPE "AuditAction" AS ENUM ('PII_VIEW','CSV_EXPORT','PII_PURGE','ADMIN_ACCOUNT_CREATE','ADMIN_ACCOUNT_DELETE');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"loginId" TEXT UNIQUE NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT UNIQUE NOT NULL,"phone" TEXT NOT NULL,"role" "UserRole" NOT NULL DEFAULT 'MEMBER',"status" "AccountStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "AuthSession" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"tokenHash" TEXT UNIQUE NOT NULL,"expiresAt" TIMESTAMP NOT NULL,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"tokenHash" TEXT UNIQUE NOT NULL,"expiresAt" TIMESTAMP NOT NULL,"usedAt" TIMESTAMP,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Campus" ("id" TEXT PRIMARY KEY,"name" TEXT UNIQUE NOT NULL,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "Course" ("id" TEXT PRIMARY KEY,"campusId" TEXT NOT NULL REFERENCES "Campus"("id"),"title" TEXT NOT NULL,"sectionTitle" TEXT,"gradeTitle" TEXT,"scheduleText" TEXT,"startDate" TIMESTAMP,"displayOrder" INTEGER NOT NULL DEFAULT 0,"intakeStatus" "IntakeStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "CourseApplication" ("id" TEXT PRIMARY KEY,"courseId" TEXT NOT NULL REFERENCES "Course"("id"),"studentName" TEXT NOT NULL,"guardianPhone" TEXT NOT NULL,"schoolName" TEXT NOT NULL,"department" TEXT NOT NULL,"grade" TEXT NOT NULL,"privacyConsentAt" TIMESTAMP NOT NULL,"purgeEligibleAt" TIMESTAMP,"retentionPolicyVersion" TEXT NOT NULL DEFAULT 'legacy-ev-0006-v1',"status" "ApplicationStatus" NOT NULL DEFAULT 'PENDING',"idempotencyKey" TEXT UNIQUE NOT NULL,"cancelledAt" TIMESTAMP,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE INDEX "CourseApplication_courseId_guardianPhone_status_idx" ON "CourseApplication"("courseId","guardianPhone","status");
CREATE TABLE "EventStatusOption" ("id" TEXT PRIMARY KEY,"label" TEXT UNIQUE NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"isClosed" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "Event" ("id" TEXT PRIMARY KEY,"campusId" TEXT REFERENCES "Campus"("id"),"managementCode" TEXT UNIQUE NOT NULL,"title" TEXT NOT NULL,"startsAt" TIMESTAMP NOT NULL,"venue" TEXT,"speaker" TEXT,"statusOptionId" TEXT NOT NULL REFERENCES "EventStatusOption"("id"),"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "EventReservation" ("id" TEXT PRIMARY KEY,"eventId" TEXT NOT NULL REFERENCES "Event"("id"),"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"grade" TEXT NOT NULL,"attendeeCount" INTEGER NOT NULL CHECK ("attendeeCount" BETWEEN 1 AND 2),"privacyConsentAt" TIMESTAMP NOT NULL,"purgeEligibleAt" TIMESTAMP,"retentionPolicyVersion" TEXT NOT NULL DEFAULT 'legacy-ev-0006-v1',"status" "ReservationStatus" NOT NULL DEFAULT 'PENDING',"idempotencyKey" TEXT UNIQUE NOT NULL,"cancelledAt" TIMESTAMP,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE INDEX "EventReservation_eventId_phone_status_idx" ON "EventReservation"("eventId","phone","status");
CREATE TABLE "PrivacyRetentionSetting" ("id" INTEGER PRIMARY KEY DEFAULT 1,"courseRetentionPolicy" TEXT NOT NULL DEFAULT '종강 및 정규 등록 안내 완료 시점 즉시 파기',"eventRetentionPolicy" TEXT NOT NULL DEFAULT '종강 및 정규 등록 안내 완료 시점 즉시 파기',"automaticPurgeEnabled" BOOLEAN NOT NULL DEFAULT false,"updatedByUserId" TEXT,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"actorUserId" TEXT,"action" "AuditAction" NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT,"filterSummary" TEXT,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "AppSetting" ("key" TEXT PRIMARY KEY,"value" TEXT NOT NULL,"createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP NOT NULL);
